const match = query.toString().match(/[\d.]+/);
const cgpa = match ? parseFloat(match[0]) : 0;

if (!cgpa || cgpa > 4.0 || cgpa < 0) {
  return "Error: Please provide valid CGPA between 0 and 4.0";
}

const maxCgpa = 4.0;
const minPass = 2.0;
const grade = 1 + 3 * ((maxCgpa - cgpa) / (maxCgpa - minPass));
const rounded = Math.round(grade * 10) / 10;

let category = "";
if (rounded <= 1.5) category = "Excellent (Sehr Gut)";
else if (rounded <= 2.5) category = "Good (Gut)";
else if (rounded <= 3.5) category = "Satisfactory (Befriedigend)";
else category = "Sufficient (Ausreichend)";

return `CGPA ${cgpa}/4.0 = German grade ${rounded} (${category})`;

