let cityInput = $fromAI('city');

// Defensive handling: if n8n/the model passes an object instead of a
// plain string (happens when the Tool's input schema isn't strictly
// defined as "string"), try to pull a usable string out of it instead
// of crashing on .toLowerCase().
if (typeof cityInput === 'object' && cityInput !== null) {
  cityInput = cityInput.city || cityInput.value || cityInput.input || JSON.stringify(cityInput);
}

const city = String(cityInput || '').toLowerCase().trim();

const cities = {
