  "heidelberg": { rent: 750, food: 250, transport: 80, insurance: 110, misc: 100, total: 1290 }
};

// Normalize German umlaut variants to their ASCII-safe keys above
const umlautMap = {
  "düsseldorf": "dusseldorf",
  "saarbrücken": "saarbrucken",
  "köln": "cologne"
};
const normalizedCity = umlautMap[city] || city;

const data = cities[normalizedCity];

if (!data) {
  return {
    error: "City not found: " + city,
    available_cities: Object.keys(cities).join(", ")
  };
}

return {
  city: normalizedCity,
  monthly_breakdown: {
    rent: "EUR " + data.rent,
